from dataclasses import dataclass


@dataclass(frozen=True)
class Money:
    amount: float | int = 0

    def __post_init__(self):
        if isinstance(self.amount, float):
            cents = round(self.amount * 100)
        else:
            cents = self.amount
        object.__setattr__(self, 'cents', cents)

    @property
    def amount(self) -> float:
        return self.cents / 100

    def __add__(self, other: "Money") -> "Money":
        return Money(amount=(self.cents + other.cents) / 100)

    def __mul__(self, qty: int) -> "Money":
        return Money(amount=(self.cents * qty) / 100)

    def __neg__(self) -> "Money":
        return Money(amount=-self.cents / 100)

    def __eq__(self, other):
        if not isinstance(other, Money):
            return False
        return self.cents == other.cents

    def __hash__(self):
        return hash(self.cents)


